// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(1000000, "Test", "TST"); }
    function testFuzz_property(address target, bool freeze, uint256 burnAmount) public {
        vm.assume(target != address(0));
        vm.assume(burnAmount > 0 && burnAmount <= c.balanceOf(address(this)));

        vm.prank(address(this));
        c.freezeAccount(target, false);

        c.burn(burnAmount);

        assertFalse(c.frozenAccount(target));
    }
}
